package com.chondrimaishrat.elearning.web; import com.chondrimaishrat.elearning.auth.SessionAccess; import com.chondrimaishrat.elearning.tutoring.*; import com.chondrimaishrat.elearning.user.*; import jakarta.servlet.http.HttpSession; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.time.LocalDateTime;
@Controller public class TutoringController {private final TutoringService tutoring;private final SessionAccess access;public TutoringController(TutoringService t,SessionAccess a){tutoring=t;access=a;}@GetMapping("/tutoring")public String page(HttpSession s,Model m){m.addAttribute("slots",tutoring.available());m.addAttribute("currentUser",s.getAttribute("currentUser"));return "tutoring";}@PostMapping("/tutoring/slots")public String create(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime startsAt,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime endsAt,@RequestParam String meetingLink,HttpSession s,RedirectAttributes r){try{tutoring.create(access.requireRole(s,UserRole.INSTRUCTOR),startsAt,endsAt,meetingLink);r.addFlashAttribute("message","Tutoring slot created.");}catch(Exception e){r.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/tutoring";}@PostMapping("/tutoring/{id}/book")public String book(@PathVariable Long id,HttpSession s,RedirectAttributes r){try{tutoring.book(access.requireRole(s,UserRole.STUDENT),id);r.addFlashAttribute("message","Tutoring session booked.");}catch(Exception e){r.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/tutoring";}}
